def schedule(tasks, capacity):
    if not tasks:
        return {"jobs": [], "makespan": 0}

    ids = set()
    for t in tasks:
        ids.add(t["id"])

    for t in tasks:
        if t["units"] > capacity:
            raise ValueError("units exceeds capacity")
        for d in t["deps"]:
            if d not in ids:
                raise ValueError("unknown dependency")

    adj = {t["id"]: [] for t in tasks}
    for t in tasks:
        for d in t["deps"]:
            adj[d].append(t["id"])

    in_degree = {t["id"]: len(t["deps"]) for t in tasks}
    queue = [tid for tid, deg in in_degree.items() if deg == 0]
    count = 0
    while queue:
        node = queue.pop(0)
        count += 1
        for nb in adj[node]:
            in_degree[nb] -= 1
            if in_degree[nb] == 0:
                queue.append(nb)
    if count != len(tasks):
        raise ValueError("circular dependency")

    task_map = {t["id"]: t for t in tasks}
    completed = set()
    started = set()
    running = []
    time = 0
    jobs = []

    while len(completed) < len(tasks):
        new_running = []
        for end_t, tid in running:
            if end_t <= time:
                completed.add(tid)
            else:
                new_running.append((end_t, tid))
        running = new_running

        available = []
        for t in tasks:
            tid = t["id"]
            if tid in started:
                continue
            if all(d in completed for d in t["deps"]):
                available.append(t)
        available.sort(key=lambda x: x["id"])

        used = sum(task_map[tid]["units"] for _, tid in running)
        for t in available:
            if t["units"] <= capacity - used:
                started.add(t["id"])
                end_time = time + t["duration"]
                running.append((end_time, t["id"]))
                jobs.append({"id": t["id"], "start": time, "end": end_time})
                used += t["units"]

        if running:
            time = min(end_t for end_t, _ in running)

    jobs.sort(key=lambda x: x["id"])
    makespan = max(j["end"] for j in jobs) if jobs else 0
    return {"jobs": jobs, "makespan": makespan}
